/**
 * One source of truth for HTTP headers. Used by:
 *   - vercel.ts            (Vercel)
 *   - public/_headers      (Cloudflare Pages / Netlify; generated by `npm run gen:hosting`, kept in sync by a test)
 *   - vite.config.ts       (`vite preview`, so the CSP can be exercised locally before shipping)
 */

/** Content-Security-Policy for the production build (no inline scripts, no eval; fonts are self-hosted). */
export const CSP = [
  "default-src 'self'",
  "script-src 'self'",
  // React sets inline style attributes (progress bar, grid columns), so styles need 'unsafe-inline'. Scripts do not.
  "style-src 'self' 'unsafe-inline'",
  // Avatars come from Supabase Storage; blob:/data: for generated downloads and previews.
  "img-src 'self' data: blob: https://*.supabase.co",
  "font-src 'self' data:",
  // Supabase REST/Auth/Functions/Storage + Realtime. If you put Supabase on a custom domain, add it here.
  "connect-src 'self' blob: data: https://*.supabase.co wss://*.supabase.co",
  "worker-src 'self'",
  "manifest-src 'self'",
  "object-src 'none'",
  "base-uri 'self'",
  "form-action 'self'",
  "frame-ancestors 'none'",
  'upgrade-insecure-requests',
].join('; ')

export interface Header {
  key: string
  value: string
}

export const SECURITY_HEADERS: Header[] = [
  { key: 'Content-Security-Policy', value: CSP },
  { key: 'Strict-Transport-Security', value: 'max-age=31536000; includeSubDomains' },
  { key: 'X-Content-Type-Options', value: 'nosniff' },
  { key: 'X-Frame-Options', value: 'DENY' },
  { key: 'Referrer-Policy', value: 'strict-origin-when-cross-origin' },
  // The app needs none of these; deny them so an injected script can't ask for them either.
  {
    key: 'Permissions-Policy',
    value: 'camera=(), microphone=(), geolocation=(), payment=(), usb=(), interest-cohort=()',
  },
  { key: 'Cross-Origin-Opener-Policy', value: 'same-origin' },
]

export const IMMUTABLE = 'public, max-age=31536000, immutable'
export const REVALIDATE = 'public, max-age=0, must-revalidate'

/** Hashed build assets never change → cache for a year. The shell and service worker must always revalidate, or users get stuck on old builds. */
export const CACHE_RULES: { source: string; value: string }[] = [
  { source: '/assets/(.*)', value: IMMUTABLE },
  { source: '/(sw.js|registerSW.js|manifest.webmanifest|index.html)', value: REVALIDATE },
]

/**
 * Headers as a plain object, for `vite preview`. `upgrade-insecure-requests` is dropped here only: it would rewrite
 * http://localhost requests (including the service worker script) to https and break local testing. Production is HTTPS-only.
 */
export const asObject = () =>
  Object.fromEntries(
    SECURITY_HEADERS.map((h) => [
      h.key,
      h.key === 'Content-Security-Policy'
        ? h.value.replace(/;\s*upgrade-insecure-requests/, '')
        : h.value,
    ]),
  )

/** Cloudflare Pages / Netlify `_headers` file. */
export function toHeadersFile(): string {
  const block = (path: string, headers: Header[]) =>
    `${path}\n${headers.map((h) => `  ${h.key}: ${h.value}`).join('\n')}\n`
  return [
    '# Generated by `npm run gen:hosting` from deploy/headers.ts — do not edit by hand.',
    block('/*', SECURITY_HEADERS),
    block('/assets/*', [{ key: 'Cache-Control', value: IMMUTABLE }]),
    block('/sw.js', [{ key: 'Cache-Control', value: REVALIDATE }]),
    block('/registerSW.js', [{ key: 'Cache-Control', value: REVALIDATE }]),
    block('/manifest.webmanifest', [{ key: 'Cache-Control', value: REVALIDATE }]),
    block('/index.html', [{ key: 'Cache-Control', value: REVALIDATE }]),
  ].join('\n')
}
